import * as Core from './core.js';
import { INTERVIEW_TYPES, QUESTION_BANK, QUESTION_FIELDS, QUESTION_TAGS, getTypeDefaults } from './data.js';
import * as IO from './import.js';
import * as Integrations from './integrations.js';
import { buildPrintDocument, PRINT_KINDS } from './print.js';
import { readStore, writeStore, STORAGE_KEY } from './storage.js';

const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), copy=v=>structuredClone(v);
const VIEWS=[['overview','준비 대시보드'],['settings','면접 기본정보'],['sessions','일정·장소'],['panels','면접위원'],['applicants','지원자 명단'],['schedule','시간 시뮬레이션'],['questions','질문·평가표'],['messages','지원자 안내'],['operations','현장 운영'],['evaluation','평가·결과'],['outputs','출력 센터'],['archive','저장·변경이력']];
const STATUSES=['예정','도착·대기','면접 중','완료','지각','결시','참여취소','일정변경'];
const RESULTS=['미정','합격','예비합격','불합격','보류','참여취소'];
let projects=[], activeId=null, stamp=null, blocked=false, view='overview', filter='', applicantSearch='', sessionFilter='', templateKey='timeConfirmed', messageFilter='all', bankField='전체', evaluationPanel='', printKind='panel', printOrientation='portrait', printSession='', printPanel='', importPreview=null, timerStart=0, timerElapsed=0, timerRunning=false;
try { const s=readStore(localStorage); projects=s.projects;activeId=s.activeId;stamp=s.stamp;if(projects.length){const v=Core.validateBackup(Core.exportBackup(projects));if(!v.valid)throw Error(v.errors.join('\n'));projects=v.projects;} }catch(e){projects=[];activeId=null;blocked=true;storageError(e.message+' 원본 저장은 유지했습니다. JSON 복원 또는 초기화 후 다시 이용하세요.');}
const project=()=>projects.find(p=>p.id===activeId);
const sessionFor=a=>project()?.sessions.find(s=>s.id===a.assignment?.sessionId);
function storageError(message){$('#storage-alert').hidden=false;$('#storage-alert').textContent=message;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){if(blocked)throw Error('저장이 중단된 상태입니다. JSON을 백업하고 복원해 주세요.');const validation=Core.validateBackup(Core.exportBackup(projects));if(!validation.valid)throw Error(validation.errors.join(' '));try{stamp=writeStore(localStorage,projects,activeId,stamp);}catch(e){blocked=true;storageError(e.message);throw e;}}
function change(fn,label='내용 변경'){const p=project(), before=Core.captureSchedule(p), backup=copy(p);try{const result=fn(p);Core.trackChanges(p,before,label);persist();render();return result;}catch(e){projects[projects.findIndex(x=>x.id===p.id)]=backup;toast(e.message);render();return false;}}
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){blocked=true;storageError('다른 탭에서 저장 내용이 바뀌었습니다. 덮어쓰기를 중단했습니다. 이 탭의 JSON 백업 후 새로고침하세요.');}});
function nav(next){view=next;filter='';render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`;}
function button(text,action,extra='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function options(items,value){return items.map(x=>{const val=typeof x==='object'?x.value:x,label=typeof x==='object'?x.label:x;return `<option value="${esc(val)}" ${val===value?'selected':''}>${esc(label)}</option>`;}).join('');}
function field(label,name,value='',type='text',help='',cls=''){return `<label class="field ${cls}">${esc(label)}<input type="${type}" name="${esc(name)}" value="${esc(value)}" ${type==='number'?'min="0" max="10000" step="1"':''}>${help?`<span class="help">${esc(help)}</span>`:''}</label>`;}
function select(label,name,value,items,help='',cls=''){return `<label class="field ${cls}">${esc(label)}<select name="${esc(name)}">${options(items,value)}</select>${help?`<span class="help">${esc(help)}</span>`:''}</label>`;}
function textarea(label,name,value='',help='',cls='full'){return `<label class="field ${cls}">${esc(label)}<textarea name="${esc(name)}">${esc(value)}</textarea>${help?`<span class="help">${esc(help)}</span>`:''}</label>`;}
function checkbox(label,name,checked=false,extra=''){return `<label class="check-label"><input type="checkbox" name="${esc(name)}" ${checked?'checked':''} ${extra}>${esc(label)}</label>`;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">INTERVIEW WORKSPACE</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,desc,action=''){return `<div class="empty"><strong>${esc(title)}</strong><p>${esc(desc)}</p>${action}</div>`;}
function table(heads,rows){return `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function metric(label,value,unit,foot){return `<div class="metric"><div class="metric-label">${label}</div><div class="value">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`;}
function assignmentText(a,p=project()){const s=p.sessions.find(s=>s.id===a.assignment?.sessionId);return s?`${s.date||'날짜 미정'} ${a.assignment.start} · ${s.label}`:'미배정';}
function modal(title,body,onSubmit,submitLabel='저장'){const d=$('#dialog');d.innerHTML=`<form id="modal-form"><h2>${esc(title)}</h2>${body}<div class="dialog-actions">${button('취소','close-dialog')}${submitLabel?`<button class="primary" type="submit">${esc(submitLabel)}</button>`:''}</div></form>`;d.showModal();$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const result=await onSubmit(data,e.currentTarget);if(result!==false)d.close();}catch(err){toast(err.message);}});}
function confirmAction(title,message,callback,label='확인 후 계속'){modal(title,`<p>${esc(message)}</p>`,()=>callback(),label);}
function download(data,name,type='application/json'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function clipboard(text){try{await navigator.clipboard.writeText(text);toast('복사했습니다. 발송 여부는 따로 확인해 주세요.');return true;}catch{modal('내용 복사',textarea('아래 내용을 선택해 복사하세요','copy',text),()=>{},'닫기');return false;}}
function render(){
 const p=project();$('#app').innerHTML=`<header class="topbar"><a class="brand" href="#" data-action="home"><span class="brand-icon">✓</span><span>면접 준비 <b>원큐</b><small>PROJECT MACH</small></span></a><div class="top-actions"><span class="save-dot">${blocked?'저장 확인 필요':'이 브라우저에 저장'}</span>${p?button('프로젝트 목록','home','','small-btn'):''}${p?button('현장 운영 ↗','nav','data-view="operations"','small-btn'):''}<a class="home-link button small-btn subtle" href="https://erakeun.github.io/ERICAAI/" target="_blank" rel="noopener noreferrer">MACH 홈 ↗</a></div></header>${p?`<div class="shell"><aside class="sidebar"><div><div class="project-label">현재 면접 프로젝트</div><div class="project-name">${esc(p.name)}</div></div><nav class="nav-group" aria-label="면접 준비 메뉴">${VIEWS.map(([key,label],i)=>button(`<span class="nav-number">${String(i+1).padStart(2,'0')}</span>${label}`,'nav',`data-view="${key}" aria-current="${view===key?'page':'false'}"`,`nav-link ${view===key?'active':''}`)).join('')}</nav><div class="sidebar-footer">V0.1 · 개인 브라우저 저장<br>기기 간 자동 동기화되지 않습니다.<br>중요한 작업은 JSON으로 보관하세요.</div></aside><main id="main" tabindex="-1">${renderView(p)}</main></div>`:landing()}`;
 if(view==='outputs'&&p)updatePreview();if(view==='sessions'&&p)document.querySelectorAll('[data-qr]').forEach(el=>Integrations.renderQRCode?.(el,Integrations.mapLink(p.sessions.find(s=>s.id===el.dataset.qr))));
}
function landing(){return `<main class="landing" id="main" tabindex="-1"><div class="landing-hero"><div><div class="eyebrow">PROJECT MACH · INTERVIEW ONEQ</div><h1>면접 준비의 모든 순서,<br>한 번에 이어지도록.</h1><p class="landing-intro">일정과 장소를 정하고, 지원자를 배정하고, 당일 운영까지.<br>반복되는 준비는 줄이고 필요한 확인은 놓치지 마세요.</p><div class="actions" style="margin-top:27px">${button('＋ 새 면접 만들기','new','','primary')}${button('지난 면접 설정 가져오기','clone-select')}${button('예시로 체험하기 →','demo','','subtle')}</div></div><div class="hero-sheet"><div class="eyebrow">YOUR NEXT INTERVIEW</div><h3>준비부터 마무리까지</h3>${[['01','일정 · 장소 · 면접위원','계획'],['02','지원자 · 시간 배정','준비'],['03','질문 · 평가표 · 안내','확인'],['04','현장 운영 · 결과 · 보관','완료']].map(([n,t,b])=>`<div class="mini-line"><time>${n}</time><span>${t}</span>${badge(b)}</div>`).join('')}<div class="progress-track"><span style="width:64%"></span></div><small>예시 화면 · 실제 준비상태는 프로젝트에서 확인</small></div></div><div class="row-between"><h2>내 면접 프로젝트 <span class="muted">${projects.length}</span></h2>${button('JSON 복원','restore','','small-btn')}</div>${projects.length?`<div class="grid-3">${projects.map(p=>`<button class="project-card" data-action="open-project" data-id="${esc(p.id)}"><div>${badge(p.type,'blue')} ${badge(p.archived?'보관됨':p.confirmed?'시간표 확정':'준비 중',p.confirmed?'good':'')}</div><strong>${esc(p.name)}</strong><small>${p.sessions.length}개 회차 <span class="bullet">·</span> 지원자 ${p.applicants.length}명</small><small>${esc(p.owner||'담당자 미입력')}</small><span class="arrow">↗</span></button>`).join('')}</div>`:empty('첫 면접을 만들어 보세요','유형별 질문·평가표·준비 체크리스트가 함께 만들어집니다.')}<p class="footer-note">입력한 내용은 이 브라우저에만 저장되며 서버로 전송하지 않습니다. 기기 간 자동 동기화되지 않습니다.<br>질문과 기한은 수정 가능한 예시입니다. 지원자의 합격 여부는 담당자가 결정합니다.</p></main>`;}
function renderView(p){return ({overview:overviewView,settings:settingsView,sessions:sessionsView,panels:panelsView,applicants:applicantsView,schedule:scheduleView,questions:questionsView,messages:messagesView,operations:operationsView,evaluation:evaluationView,outputs:outputsView,archive:archiveView}[view]||overviewView)(p);}
function warnings(p){const w=[];const add=(title,desc,to)=>w.push({title,desc,to});if(!p.sessions.length)add('면접 회차를 추가하세요','날짜·면접실별로 회차를 나누어 설정합니다.','sessions');for(const s of p.sessions){if(!s.date)add(`${s.label}: 날짜가 필요합니다`,'면접일을 입력해야 시간표를 확정할 수 있습니다.','sessions');if(s.venue.reservation!=='예약 확정')add(`${s.label}: 장소 예약 확인`,'예약상태와 장소 사용시간을 확인해 주세요.','sessions');if(!s.panelistIds.length)add(`${s.label}: 참여위원 선택`,'위원 Pool에서 해당 회차에 참여하는 분을 지정하세요.','panels');}
 const un=p.applicants.filter(a=>!a.assignment&&a.status!=='참여취소').length;if(un)add(`지원자 ${un}명 미배정`,'회차를 추가하거나 운영시간을 조정한 뒤 배정하세요.','schedule');if(!p.applicants.length)add('지원자 명단을 등록하세요','직접 입력 또는 Excel·CSV를 가져올 수 있습니다.','applicants');
 for(const issue of Core.sessionConflicts(p))add(issue.message,'회차 시간·장소 또는 참여위원을 조정하세요.','sessions');for(const x of Core.scoreWarnings(p))add(typeof x==='string'?x:x.message,'평가항목 배점을 목표 총점과 맞춰 주세요.','questions');
 const selected=p.questions.filter(q=>q.selected);if(!selected.length)add('사용할 질문을 선택하세요','질문은행에서 추가하거나 직접 작성할 수 있습니다.','questions');const duration=selected.reduce((sum,q)=>sum+(+q.minutes||0),0);if(p.sessions.some(s=>duration>s.interviewMinutes))add(`질문 예상시간 ${duration}분`,'일부 회차의 실제 면접시간보다 깁니다. 질문 수나 시간을 조정하세요.','questions');
 const re=p.applicants.filter(a=>a.message?.needsUpdate).length;if(re)add(`${re}명 재안내 필요`,'확정 안내 후 일정 또는 장소가 바뀌었습니다.','messages');if(Core.stalePrints(p).length)add('기존 출력물 재출력 필요','현재 문서 버전으로 다시 출력하고 실물을 확인하세요.','outputs');return w;}
function overviewView(p){const ws=warnings(p),assigned=p.applicants.filter(a=>a.assignment).length,done=p.checklist.filter(c=>c.done).length,total=p.checklist.length,pct=total?Math.round(done/total*100):0;return heading('오늘, 무엇부터 준비할까요?',`${p.name} · 준비 현황을 확인하고 필요한 단계로 바로 이동하세요.`,`${badge(p.confirmed?'시간표 확정':'시간표 초안',p.confirmed?'good':'blue')}${button('출력 센터 →','nav','data-view="outputs"')}`)+`<div class="metrics">${metric('등록된 지원자',p.applicants.length,'명',`배정 ${assigned}명 · 미배정 ${p.applicants.length-assigned}명`)}${metric('면접 일정',p.sessions.length,'회차',new Set(p.sessions.map(s=>s.date).filter(Boolean)).size+'개 날짜 · 복수 면접실 지원')}${metric('면접위원 Pool',p.panelists.length,'명',p.sessions.reduce((n,s)=>n+s.panelistIds.length,0)+'건 회차 참여')}${metric('준비 체크리스트',pct,'%',`${done} / ${total}개 확인`)}</div><div class="grid-2"><section class="card"><div class="card-header"><h2>지금 해야 할 일</h2>${badge(ws.length+'건 확인',ws.length?'warn':'good')}</div>${ws.length?ws.slice(0,6).map(w=>`<div class="task-row"><span class="task-icon">!</span><div class="row-body"><strong>${esc(w.title)}</strong><small>${esc(w.desc)}</small></div>${button('확인 →','nav',`data-view="${w.to}"`,'small-btn subtle')}</div>`).join(''):'<div class="empty">현재 설정에서 확인이 필요한 항목이 없습니다.</div>'}${ws.length>6?`<details><summary>나머지 ${ws.length-6}개 확인</summary>${ws.slice(6).map(w=>`<div class="task-row"><div class="row-body">${esc(w.title)}</div>${button('확인','nav',`data-view="${w.to}"`,'small-btn')}</div>`).join('')}</details>`:''}</section><section class="card"><div class="card-header"><h2>면접 일정</h2>${button('일정 관리 ↗','nav','data-view="sessions"','small-btn subtle')}</div>${p.sessions.length?p.sessions.map(s=>`<div class="session-row"><div class="date-tile"><small>${esc(s.date.slice(5,7)||'월')}</small><strong>${esc(s.date.slice(8)||'—')}</strong></div><div class="row-body"><strong>${esc(s.label)}</strong><small class="help">${esc(s.start)}–${esc(s.end)} · ${esc(s.venue.building||'장소 미정')} ${esc(s.venue.room)}</small><small class="help">${p.applicants.filter(a=>a.assignment?.sessionId===s.id).length}명 배정 · 위원 ${s.panelistIds.length}명</small></div>${badge(s.venue.reservation,s.venue.reservation==='예약 확정'?'good':'warn')}</div>`).join(''):empty('등록된 일정이 없습니다','먼저 면접 날짜와 장소를 정해 주세요.')}</section></div><section class="card"><div class="card-header"><div><h2>빠짐없이, 준비 체크리스트</h2><small>기한은 담당자가 정하는 운영 예시이며 공식 규정이 아닙니다.</small></div>${button('항목 추가','checklist-add','','small-btn')}</div><div class="progress-track"><span style="width:${pct}%"></span></div>${p.checklist.map(c=>`<div class="checklist-row"><input type="checkbox" aria-label="${esc(c.label)} 완료" data-check="${esc(c.id)}" ${c.done?'checked':''}><span>${esc(c.label)}</span><input type="date" aria-label="${esc(c.label)} 기한" data-deadline="${esc(c.id)}" value="${esc(c.due||'')}">${button('수정','checklist-edit',`data-id="${esc(c.id)}"`,'small-btn subtle')}</div>`).join('')}</section>`;}
function settingsView(p){return heading('면접 기본정보','한 프로젝트에서 여러 모집분야와 날짜를 함께 관리할 수 있습니다.')+`<form id="settings-form" class="card"><div class="form-grid">${field('프로젝트명','name',p.name,'text','면접을 구분할 이름입니다.','span-2')}${select('면접유형','type',p.type,INTERVIEW_TYPES,'유형 변경은 작성한 질문·평가표를 덮어쓰지 않습니다.')}${field('모집분야','field',p.field,'text','복수 분야는 쉼표로 구분합니다.','span-2')}${field('담당자','owner',p.owner)}${field('운영기간 시작','startDate',p.startDate||'','date')}${field('운영기간 종료','endDate',p.endDate||'','date')}${field('문의처','inquiry',p.inquiry,'text','지원자 안내에 표시할 연락처입니다.')}${field('회신기한','replyBy',p.replyBy,'text','예: 10월 10일 18시')}${field('보관 검토일','retentionDate',p.retentionDate||'','date','기관의 실제 보관 기준에 따라 설정하세요.')}${select('평가표 지원자 표시','displayMode',p.displayMode||'name-number',[{value:'name-number',label:'이름 + 번호'},{value:'number',label:'번호만'},{value:'custom',label:'사용자 정의'}])}${field('사용자 정의 표시','customDisplay',p.customDisplay||'{번호} / {지원분야}','text','{이름}, {번호}, {지원분야}를 사용할 수 있습니다.','full')}${textarea('지원자 준비물','materials',p.materials,'확정 안내 후 변경하면 해당 지원자에게 재안내가 표시됩니다.')}${textarea('면접 진행방법','protocol',p.protocol||'','위원용 자료에 포함됩니다. 입실·질문·평가 순서를 작성하세요.')}${textarea('내부 운영메모','operatingNotes',p.operatingNotes||'','운영자용 자료에만 포함됩니다.')}</div><div class="actions" style="margin-top:22px"><button class="primary" type="submit">기본정보 저장</button></div></form><div class="notice info">입력값은 이 브라우저에 저장됩니다. 브라우저 데이터를 지우면 사라질 수 있으므로 저장·변경이력에서 JSON을 정기적으로 백업해 주세요.</div>`;}
function sessionsView(p){return heading('일정과 장소를 함께 정하세요','오전·오후, 다른 날짜, 병렬 면접실을 각각 하나의 회차(Session)로 등록합니다.',button('＋ 회차 추가','session-add','','primary'))+(!p.sessions.length?`<section class="card">${empty('첫 회차를 추가하세요','면접시간과 장소 사용시간을 구분해 입력합니다.')}</section>`:p.sessions.map(s=>{const slots=Core.generateSlots(s);return `<section class="card"><div class="card-header"><div><h2>${esc(s.label)} ${badge(s.mode==='group'?'조별 면접':'개인 면접','blue')}</h2><small>${esc(s.date||'날짜 미정')} · ${esc(s.start)}–${esc(s.end)}</small></div><div class="actions">${button('수정','session-edit',`data-id="${esc(s.id)}"`)}${button('삭제','session-delete',`data-id="${esc(s.id)}"`,'small-btn danger')}</div></div><div class="grid-3"><div><div class="section-label">면접 운영</div><strong>${s.interviewMinutes}분 면접 + ${s.turnoverMinutes}분 평가·교체</strong><p class="help">슬롯 ${+s.interviewMinutes + +s.turnoverMinutes}분 · ${slots.length}개 슬롯 · 최대 ${slots.length*(s.mode==='group'?s.groupSize:1)}명<br>${s.mode==='group'?`${s.groupSize}명이 한 슬롯을 함께 사용합니다.`:'한 슬롯에 한 명을 배정합니다.'}</p></div><div><div class="section-label">장소</div><strong>${esc(s.venue.campus)} ${esc(s.venue.building||'건물 미정')} ${esc(s.venue.room)}</strong><p class="help">대기실 ${esc(s.venue.waitingRoom||'미정')} · 접수 ${esc(s.venue.reception||'미정')}<br>장소 사용 ${esc(s.venue.useStart||'미정')}–${esc(s.venue.useEnd||'미정')}</p>${badge(s.venue.reservation,s.venue.reservation==='예약 확정'?'good':'warn')}</div><div><div class="section-label">참여위원</div><strong>${s.panelistIds.map(id=>esc(p.panelists.find(x=>x.id===id)?.name||'삭제된 위원')).join(' · ')||'참여위원 미선택'}</strong><p class="help">${s.breaks.length?`휴식 ${s.breaks.map(b=>esc(b.start)+'–'+esc(b.end)).join(', ')}`:'등록된 휴식 없음'}<br>도착 권장 ${s.arrivalMinutes}분 전 · ${esc(s.field||'전체 모집분야')}</p></div></div>${s.venue.campus==='ERICA'?`<details><summary>건물 위치·QR 확인</summary><div class="actions"><a class="button small-btn" href="${esc(Integrations.mapLink(s))}" target="_blank" rel="noopener noreferrer">캠퍼스맵 열기 ↗</a>${button('위치링크 복사','map-copy',`data-id="${esc(s.id)}"`,'small-btn')}</div><p class="help">${esc(Integrations.locationInfo(s).guidance)} QR은 같은 위치 링크를 담습니다.</p><div data-qr="${esc(s.id)}"></div></details>`:''}</section>`;}).join(''))+`<div class="notice info">조별 ‘3명 / 면접 18분 + 교체 2분’은 그룹 전체 슬롯 20분입니다. 운영 종료를 넘기는 슬롯은 생성하지 않습니다.</div>`;}
function panelsView(p){return heading('회차별 면접위원을 구성하세요','위원 Pool에 등록한 뒤, 실제 참여하는 회차와 참석확인을 구분해 관리합니다.',button('＋ 위원 등록','panel-add','','primary'))+`<section class="card"><div class="card-header"><h2>면접위원 Pool</h2><div class="actions">${button('면접위원 명패 만들기 ↗','nameplates','','small-btn')}</div></div>${p.panelists.length?table(['이름 / 역할','소속 · 직위','연락처','관리'],p.panelists.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br>${esc(x.role)}</td><td>${esc(x.organization)}<br>${esc(x.position)}</td><td>${esc(x.contact||'—')}</td><td><div class="actions">${button('수정','panel-edit',`data-id="${esc(x.id)}"`,'small-btn')}${button('삭제','panel-delete',`data-id="${esc(x.id)}"`,'small-btn danger')}</div></td></tr>`)):empty('위원을 등록하세요','연락처는 선택 입력이며 명패 파일에는 포함되지 않습니다.')}</section><section class="card"><h2>회차별 참여 및 참석확인</h2>${p.sessions.length?p.sessions.map(s=>`<div class="session-row"><div class="row-body"><h3>${esc(s.label)} <small>${esc(s.date)} ${esc(s.start)}–${esc(s.end)}</small></h3>${p.panelists.map(x=>`<div class="row-between" style="margin-top:9px"><label class="check-label"><input type="checkbox" data-panel-session="${esc(s.id)}" data-id="${esc(x.id)}" ${s.panelistIds.includes(x.id)?'checked':''}>${esc(x.name)} · ${esc(x.role)}</label>${s.panelistIds.includes(x.id)?`<select aria-label="${esc(x.name)} ${esc(s.label)} 참석확인" data-attendance="${esc(s.id)}" data-id="${esc(x.id)}">${options(['미응답','요청함','참석','불참'],x.attendance?.[s.id]||'미응답')}</select>`:''}</div>`).join('')}</div></div>`).join(''):empty('회차를 먼저 등록하세요','일정·장소 화면에서 추가할 수 있습니다.')}</section>${Core.sessionConflicts(p).map(x=>`<div class="notice error">${esc(x.message)} 회차 시간 또는 위원을 조정하세요.</div>`).join('')}`;}
function applicantsView(p){let list=p.applicants.filter(a=>(!applicantSearch||[a.name,a.number,a.field].some(x=>x.includes(applicantSearch)))&&(!filter||(filter==='unassigned'&&!a.assignment)||(filter==='change'&&a.changeRequest)));return heading('지원자 명단을 한 번에 정리하세요','이름·지원자번호만 필수입니다. 동명이인은 별도 내부 ID로 안전하게 구분됩니다.',`${button('여러 행 붙여넣기','paste')}${button('CSV·Excel 가져오기','import-applicants')}${button('＋ 직접 입력','applicant-add','','primary')}`)+`<section class="card"><div class="filters"><label class="field">이름·번호·분야 검색<input id="applicant-search" value="${esc(applicantSearch)}" placeholder="검색 후 Enter"></label><label class="field">표시 대상<select id="applicant-filter">${options([{value:'',label:'전체 지원자'},{value:'unassigned',label:'미배정'},{value:'change',label:'일정변경 요청'}],filter)}</select></label>${button('가져오기 양식 받기','import-template','','small-btn')}</div><p class="help">총 ${p.applicants.length}명 · 표시 ${list.length}명 · 기존 번호를 입력하거나 비워 두면 유형별 번호가 자동 생성됩니다.</p>${list.length?table(['번호 / 이름','지원분야','배정 일정','안내 · 현장','관리'],list.map(a=>`<tr><td><strong>${esc(a.number)}</strong><br>${esc(a.name)} ${a.locked||a.fixed?'🔒':''}<small class="help">${esc(a.contact)}</small></td><td>${esc(a.field||'—')}${a.changeRequest?badge('일정변경 요청','warn'):''}</td><td>${esc(assignmentText(a))}${a.available?.length||a.unavailable?.length?'<small class="help">가능·불가시간 조건 있음</small>':''}</td><td>${badge(a.message?.needsUpdate?'재안내 필요':a.message?.sent?'발송확인':a.message?.generated?'생성됨':'미안내',a.message?.needsUpdate?'warn':'')}<br>${badge(a.status)}</td><td><div class="actions">${button('수정','applicant-edit',`data-id="${esc(a.id)}"`,'small-btn')}${button('배정','move',`data-id="${esc(a.id)}"`,'small-btn')}${button('삭제','applicant-delete',`data-id="${esc(a.id)}"`,'small-btn danger')}</div></td></tr>`)):empty('표시할 지원자가 없습니다','직접 입력하거나 CSV·Excel을 가져오세요.')}</section><div class="notice info">가져온 파일은 브라우저 안에서만 처리합니다. 지원자번호 중복·누락을 미리보기에서 확인한 뒤 등록합니다. 동일한 이름은 자동으로 합치지 않습니다.</div>`;}
function scheduleView(p){const sim=Core.simulate(p),un=p.applicants.filter(a=>!a.assignment&&a.status!=='참여취소'),slotCount=p.sessions.reduce((n,s)=>n+Core.generateSlots(s).length,0),cap=p.sessions.reduce((n,s)=>n+Core.generateSlots(s).reduce((sum,x)=>sum+x.capacity,0),0);return heading('여러 날짜를 하나의 시간표로','가능시간·휴식·분야를 반영합니다. 고정하거나 연락 후 잠근 지원자는 재배정에서 제외됩니다.',`${button(p.confirmed?'시간표 확정 해제':'시간표 확정',p.confirmed?'unconfirm-schedule':'confirm-schedule')}${button('자동배정 / 다시 배정','auto-assign','','primary')}`)+`<div class="metrics">${metric('배정 대상',p.applicants.filter(a=>a.status!=='참여취소').length,'명','참여취소 제외')}${metric('만들어진 슬롯',slotCount,'개',p.sessions.length+'개 회차 · 휴식 반영')}${metric('총 수용인원',cap,'명','조별 슬롯은 조 인원 반영')}${metric('현재 미배정',un.length,'명','부족한 시간은 임의로 줄이지 않습니다.')}</div>${p.confirmed?'<div class="notice info">시간표가 확정되었습니다. 이후 변경은 이력에 남고, 발송 확인한 지원자는 재안내 대상으로 표시됩니다.</div>':''}${un.length?`<div class="notice">${p.applicants.length}명 중 ${p.applicants.filter(a=>a.assignment).length}명 배정, ${un.length}명 미배정입니다. ${button('운영시간 수정·회차 추가 →','nav','data-view="sessions"','small-btn subtle')}</div>`:''}${(Core.assignmentIssues?.(p)||[]).map(x=>`<div class="notice error">${esc(x.number)}: ${esc(x.message)}</div>`).join('')}<section class="card"><div class="card-header"><h2>계획 단계 시뮬레이션</h2><small>지원자 등록 전에도 인원을 바꿔 확인할 수 있습니다.</small></div><div class="filters">${field('계획 인원','plannedCount',p.plannedCount??p.applicants.length,'number')}${button('계산','simulate','','small-btn')}</div><div id="simulation-summary" class="notice info">계획 ${p.plannedCount??p.applicants.length}명 / 수용 ${cap}명 · 최소 부족 ${Math.max(0,(p.plannedCount??p.applicants.length)-cap)}명. 최소 부족 슬롯 ${Math.ceil(Math.max(0,(p.plannedCount??p.applicants.length)-cap)/Math.max(1,...p.sessions.map(s=>s.mode==='group'?s.groupSize:1)))}개 (가장 큰 조 인원 기준). 회차 운영시간 합계 ${sim.operatingMinutes}분. 개인별 조건 때문에 실제 배정 가능 인원은 줄어들 수 있습니다.</div>${table(['회차','슬롯 계산','휴식 반영 슬롯 / 인원','마지막 슬롯 종료'],p.sessions.map(s=>{const slots=Core.generateSlots(s);return `<tr><td>${esc(s.date)} ${esc(s.label)}</td><td>${s.interviewMinutes} + ${s.turnoverMinutes} = ${+s.interviewMinutes + +s.turnoverMinutes}분</td><td>${slots.length}개 / ${slots.reduce((n,x)=>n+x.capacity,0)}명</td><td>${slots.at(-1)?.blockEnd||'생성 불가'}</td></tr>`;}))}</section><section class="card"><div class="card-header"><h2>면접 시간표</h2><small>지원자를 끌어 놓거나 ‘이동’으로 날짜·회차를 변경하세요.</small></div>${p.sessions.length?`<div class="schedule-board">${p.sessions.map(s=>`<div class="schedule-column"><h3>${esc(s.label)}</h3><small>${esc(s.date)} · ${esc(s.venue.room||'면접실 미정')}</small>${Core.generateSlots(s).map(slot=>`<div class="slot" data-slot-session="${esc(s.id)}" data-start="${slot.start}"><div class="slot-time">${slot.start}–${slot.end} <small>교체 후 ${slot.blockEnd} · ${slot.capacity}명</small></div>${p.applicants.filter(a=>a.assignment?.sessionId===s.id&&a.assignment.start===slot.start&&a.status!=='참여취소').map(a=>`<div class="person-chip ${a.locked||a.fixed?'locked':''}" draggable="${!a.locked&&!a.fixed}" data-person="${esc(a.id)}"><span>${esc(a.number)} ${esc(a.name)} ${a.locked||a.fixed?'🔒':''}</span>${button('이동','move',`data-id="${esc(a.id)}"`,'small-btn subtle')}</div>`).join('')}</div>`).join('')||'<p class="help">날짜·시간 설정을 확인하세요.</p>'}</div>`).join('')}</div>`:empty('회차를 먼저 추가하세요','일정·장소에서 날짜와 시간 조건을 설정합니다.')}</section>${un.length?`<section class="card"><h2>미배정 지원자 ${un.length}명</h2><div class="actions">${un.map(a=>button(`${esc(a.number)} ${esc(a.name)} →`,'move',`data-id="${esc(a.id)}"`,'small-btn')).join('')}</div></section>`:''}`;}
function questionsView(p){const selected=p.questions.filter(q=>q.selected),time=selected.reduce((n,q)=>n+(+q.minutes||0),0),sum=p.criteria.reduce((n,c)=>n+(+c.max||0),0),bank=QUESTION_BANK.filter(q=>bankField==='전체'||q.field===bankField);return heading('질문과 평가기준을 맞추세요','동일 질문·동일 평가기준을 프로젝트 전체에 적용합니다. 모든 예시는 자유롭게 수정할 수 있습니다.',button('＋ 질문 직접 작성','question-add','','primary'))+`<section class="card"><div class="card-header"><div><h2>이번 면접의 질문 ${selected.length}개</h2><small>예상 총 ${time}분 · 실제 면접시간과 비교해 주세요.</small></div>${badge(p.sessions.some(s=>time>s.interviewMinutes)?'시간 초과 확인':'질문 준비',p.sessions.some(s=>time>s.interviewMinutes)?'warn':'blue')}</div>${p.questions.length?p.questions.map((q,i)=>`<div class="task-row"><input type="checkbox" aria-label="질문 사용 ${esc(q.text)}" data-question-selected="${esc(q.id)}" ${q.selected?'checked':''}><div class="row-body"><div>${badge(q.field)} ${badge(q.tag)} <small>${q.minutes}분</small></div><strong>${esc(q.text)}</strong>${q.followUp?`<small>후속: ${esc(q.followUp)}</small>`:''}<small>연결 평가: ${esc(p.criteria.find(c=>c.id===q.criterionId)?.label||'미연결')}</small></div><div class="actions">${button('↑','question-up',`data-id="${esc(q.id)}"`,'small-btn')}${button('수정','question-edit',`data-id="${esc(q.id)}"`,'small-btn')}${button('삭제','question-delete',`data-id="${esc(q.id)}"`,'small-btn danger')}</div></div>`).join(''):empty('등록된 질문이 없습니다','질문은행에서 담거나 직접 작성하세요.')}</section><section class="card"><div class="card-header"><h2>질문은행 <small>44개 예시</small></h2><select aria-label="질문은행 분야" id="bank-field">${options(['전체',...QUESTION_FIELDS],bankField)}</select></div><div class="review-lines">${bank.map(q=>`<div class="task-row"><div class="row-body"><small>${esc(q.field)} · ${esc(q.tag)}</small><strong>${esc(q.text)}</strong></div>${button('＋ 담기','bank-add',`data-id="${esc(q.id)}"`,'small-btn')}</div>`).join('')}</div></section><section class="card"><div class="card-header"><h2>수정 가능한 평가표</h2><div class="actions">${button('평가항목 추가','criterion-add','','small-btn')}${button('A4 평가표 보기','print-evaluation','','small-btn')}</div></div><div class="filters">${field('목표 총점','targetScore',p.targetScore,'number')}${button('목표 총점 저장','target-score','','small-btn')}<strong>${sum} / ${p.targetScore}점 ${badge(sum===+p.targetScore?'배점 일치':'배점 합계 오류',sum===+p.targetScore?'good':'bad')}</strong></div>${p.criteria.map((c,i)=>`<div class="task-row"><span class="task-icon">${i+1}</span><div class="row-body"><strong>${esc(c.label)} · ${c.max}점</strong><small>${esc(c.description)}</small><small>기준: ${esc(c.rubric)}</small></div><div class="actions">${button('↑','criterion-up',`data-id="${esc(c.id)}"`,'small-btn')}${button('수정','criterion-edit',`data-id="${esc(c.id)}"`,'small-btn')}${button('삭제','criterion-delete',`data-id="${esc(c.id)}"`,'small-btn danger')}</div></div>`).join('')}<p class="help">미입력 점수는 0점으로 계산하지 않습니다. 평가기준 변경 후 기존 평가와 출력물을 다시 확인하세요.</p></section>`;}
function messageText(p,a,key){const s=p.sessions.find(s=>s.id===a.assignment?.sessionId),arrival=s&&a.assignment?Core.toTime(Math.max(0,Core.toMinutes(a.assignment.start)-s.arrivalMinutes)):'';const values={'이름':a.name,'번호':a.number,'면접명':p.name,'일자':s?.date,'면접시간':a.assignment?.start,'도착권장시간':arrival,'건물':s?[s.venue.campus,s.venue.building].filter(Boolean).join(' '):'','면접실':s?.venue.room,'대기실':s?.venue.waitingRoom,'준비물':p.materials,'회신기한':p.replyBy,'문의처':p.inquiry,'캠퍼스맵 링크':s?.venue.campus==='ERICA'?Integrations.mapLink(s):'','지원분야':a.field,'예비순번':a.reserveRank};return (p.templates[key]?.text||'').replace(/\{([^}]+)\}/g,(_,k)=>values[k]!==undefined&&values[k]!==''?String(values[k]):`[${k} 확인 필요]`);}
function isResultTemplate(key){return ['accepted','reserve','rejected'].includes(key);}
function messageAllowed(p,a,key){if(isResultTemplate(key)){return a.resultConfirmed&&({accepted:'합격',reserve:'예비합격',rejected:'불합격'}[key]===a.result);}return !!a.assignment&&a.status!=='참여취소';}
function messagesView(p){if(!p.templates[templateKey])templateKey=Object.keys(p.templates)[0];let list=p.applicants.filter(a=>(messageFilter!=='changed'||a.message?.needsUpdate)&&(messageFilter!=='unsent'||!(isResultTemplate(templateKey)?a.resultMessage:a.message)?.sent)&&messageAllowed(p,a,templateKey));return heading('개별 안내를 준비하고 확인하세요','생성·복사, 발송확인, 회신확인을 구분합니다. 실제 SMS·이메일을 발송하지 않습니다.')+`<section class="card"><div class="filters"><label class="field">안내 유형<select id="message-template">${options(Object.entries(p.templates).map(([value,v])=>({value,label:v.label})),templateKey)}</select></label><label class="field">표시 대상<select id="message-filter">${options([{value:'all',label:'전체 대상자'},{value:'changed',label:'재안내 대상만'},{value:'unsent',label:'아직 발송 미확인'}],messageFilter)}</select></label>${button('문구 수정','template-edit')}${button('전체 목록 복사','messages-copy','','primary')}</div><p class="help">사용 가능 변수: {이름}, {번호}, {면접명}, {일자}, {면접시간}, {도착권장시간}, {건물}, {면접실}, {대기실}, {준비물}, {회신기한}, {문의처}, {캠퍼스맵 링크}, {예비순번}</p>${isResultTemplate(templateKey)?'<div class="notice info">담당자가 최종 확정한 결과와 안내 유형이 일치하는 지원자만 표시합니다.</div>':!p.confirmed?'<div class="notice">시간표 초안입니다. 안내 내용을 검토할 수 있지만, 발송확인은 시간표 확정 후 가능합니다.</div>':''}</section><div class="list-stack">${list.map(a=>{const m=isResultTemplate(templateKey)?a.resultMessage||{}:a.message;return `<article class="message-card"><div class="row-between"><strong>${esc(a.number)} ${esc(a.name)}</strong><div>${badge(m.generated?'생성됨':'미생성')} ${badge(m.sent?'발송확인':'발송 미확인',m.sent?'good':'')} ${m.needsUpdate?badge('재안내 필요','warn'):''}</div></div><div class="message-text">${esc(messageText(p,a,templateKey))}</div><div class="actions">${button('문구 복사','message-copy',`data-id="${esc(a.id)}"`)}${button(m.sent?'발송 확인됨':'발송확인','message-sent',`data-id="${esc(a.id)}"`,'small-btn')}${button(m.replied?'회신 확인됨':'회신확인','message-replied',`data-id="${esc(a.id)}"`,'small-btn')}</div></article>`;}).join('')||`<section class="card">${empty('해당 안내 대상이 없습니다','시간배정 또는 최종 결과 확정 상태를 확인하세요.')}</section>`}</div>`;}
function operationsView(p){const sessions=sessionFilter?p.sessions.filter(s=>s.id===sessionFilter):p.sessions;let list=p.applicants.filter(a=>a.assignment&&sessions.some(s=>s.id===a.assignment.sessionId)).sort((a,b)=>`${sessionFor(a)?.date} ${a.assignment.start}`.localeCompare(`${sessionFor(b)?.date} ${b.assignment.start}`));const current=list.filter(a=>a.status==='면접 중'),next=list.filter(a=>['예정','도착·대기','지각'].includes(a.status)),waiting=list.filter(a=>a.status==='도착·대기');const now=new Date(),day=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');const delays=current.filter(a=>sessionFor(a)?.date===day).map(a=>Math.max(0,now.getHours()*60+now.getMinutes()-(Core.toMinutes(a.assignment.start)+sessionFor(a).interviewMinutes)));return heading('면접 당일, 현재 상황에 집중하세요','예정 시간은 자동으로 당겨지지 않습니다. 지각·결시 상태가 결과를 바꾸지 않습니다.',button('대기실 화면','waiting-display'))+`<div class="filters"><label class="field">운영 회차<select id="session-filter">${options([{value:'',label:'전체 회차'},...p.sessions.map(s=>({value:s.id,label:`${s.date} ${s.label}`}))],sessionFilter)}</select></label><p class="help">예정 종료 ${esc(sessions.map(s=>`${s.label} ${s.end}`).join(' · ')||'미정')}</p></div><div class="live-board"><div><small>현재 면접 중</small><div class="live-number">${current.map(a=>esc(a.number)).join(' · ')||'대기 중'}</div><div>${current.map(a=>esc(a.name)).join(' · ')||'상태를 ‘면접 중’으로 바꾸면 표시됩니다.'}</div></div><div><small>다음 예정 / 대기자</small><div class="live-number">${esc(next[0]?.number||'—')}</div><div>${next[0]?.assignment.start||''} · 대기 ${waiting.length}명</div></div><div><small>현재 초과시간 · ${day}</small><div class="live-number">${delays.length?Math.max(...delays):0}<small> 분</small></div><div class="actions"><span class="timer" id="timer">${formatTimer()}</span>${button(timerRunning?'정지':'타이머 시작','timer-toggle','','small-btn')}${button('초기화','timer-reset','','small-btn')}</div></div></div><section class="card operations-list">${list.length?table(['예정 / 도착 권장','번호 / 이름','현장 상태','일정변경 요청 / 메모'],list.map(a=>{const s=sessionFor(a);return `<tr><td data-label="예정 / 도착 권장"><strong>${esc(a.assignment.start)}</strong><br><small>${esc(s.date)} · ${esc(s.label)}</small><br><small>도착 ${Core.toTime(Math.max(0,Core.toMinutes(a.assignment.start)-s.arrivalMinutes))}</small></td><td data-label="번호 / 이름">${esc(a.number)}<br>${esc(a.name)}</td><td data-label="현장 상태"><select aria-label="${esc(a.number)} 현장 상태" data-status="${esc(a.id)}">${options(STATUSES,a.status)}</select></td><td data-label="일정변경 요청 / 메모">${esc(a.changeRequest||a.note||'—')}<br>${button('기록 수정','applicant-edit',`data-id="${esc(a.id)}"`,'small-btn subtle')}</td></tr>`;})):empty('배정된 지원자가 없습니다','시간표에서 먼저 배정해 주세요.')}</section>`;}
function formatTimer(){const secs=Math.floor((timerElapsed+(timerRunning?Date.now()-timerStart:0))/1000);return `${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
setInterval(()=>{if($('#timer'))$('#timer').textContent=formatTimer();},1000);
function evaluationView(p){const panel=p.panelists.find(x=>x.id===evaluationPanel)||p.panelists[0];evaluationPanel=panel?.id||'';return heading('평가 누락을 확인하고 결과를 정리하세요','점수는 단순 합계·평균만 계산합니다. 합격·예비합격·불합격은 담당자가 직접 지정하고 최종 확정합니다.',button('결과 검토·최종 확정','finalize-results','','primary'))+`<section class="card"><div class="card-header"><h2>위원별 평가 입력</h2><select id="evaluation-panel" aria-label="평가위원">${options(p.panelists.map(x=>({value:x.id,label:x.name+' · '+x.role})),evaluationPanel)}</select></div><p class="help">회차에 참여하는 위원만 평가합니다. 빈칸은 미입력이고, ‘0’은 입력된 0점입니다. 한 지원자의 점수를 입력한 뒤 ‘점수 저장’을 누르세요.</p>${table(['지원자',...p.criteria.map(c=>`${esc(c.label)}<br><small>/${c.max}</small>`),'상태 / 의견'],p.applicants.filter(a=>sessionFor(a)?.panelistIds.includes(evaluationPanel)).map(a=>{const ev=a.evaluations?.[evaluationPanel]||{scores:{}};const summary=Core.evaluationSummary(p,a);return `<tr><td>${esc(a.number)}<br>${esc(a.name)}</td>${p.criteria.map(c=>`<td><input type="number" class="score-input" min="0" max="${c.max}" step="0.1" aria-label="${esc(a.number)} ${esc(c.label)} 점수" data-score-applicant="${esc(a.id)}" data-criterion="${esc(c.id)}" value="${esc(ev.scores?.[c.id]??'')}" placeholder="미입력"></td>`).join('')}<td>${badge(summary.complete?'평가 완료':'누락 확인',summary.complete?'good':'warn')}${button('점수 저장','evaluation-save',`data-id="${esc(a.id)}"`,'small-btn')}${button('의견','evaluation-comment',`data-id="${esc(a.id)}"`,'small-btn subtle')}</td></tr>`;}))}${!panel?empty('면접위원을 먼저 등록하세요','회차별 참여위원이 있어야 평가할 수 있습니다.'):''}</section><section class="card"><h2>담당자 결과 검토</h2><div class="notice info">평가가 누락되거나 결과가 ‘미정’이면 최종 확정할 수 없습니다. 취소·결시 등 평가 제외 사유가 있는 경우 지원자별 사유를 기록하고 담당자가 직접 확인합니다.</div>${table(['지원자','평가 상태 / 단순 평균','결과 입력','예비순번','최종 확인'],p.applicants.map(a=>{const summary=Core.evaluationSummary(p,a);return `<tr><td><strong>${esc(a.number)}</strong><br>${esc(a.name)}<small class="help">${esc(a.field)}</small></td><td>${badge(summary.complete?'완료':'평가 미완료',summary.complete?'good':'warn')}<br><small>${summary.complete?`평균 ${summary.average??'—'}점`:esc((summary.missing||[]).map(x=>typeof x==='string'?x:x.message||x.panelistName||'누락').join(' · ')||'필수 항목 확인')}</small>${button('누락 상세','evaluation-details',`data-id="${esc(a.id)}"`,'small-btn subtle')}</td><td><select aria-label="${esc(a.number)} 결과" data-result="${esc(a.id)}">${options(RESULTS,a.result)}</select></td><td><input type="number" min="1" step="1" aria-label="${esc(a.number)} 예비순번" data-rank="${esc(a.id)}" value="${esc(a.reserveRank??'')}" ${a.result==='예비합격'?'':'disabled'}></td><td>${badge(a.resultConfirmed?'담당자 확정':'미확정',a.resultConfirmed?'good':'')}<br>${button('평가 제외 사유','evaluation-exempt',`data-id="${esc(a.id)}"`,'small-btn subtle')}${a.evaluationExemptReason?`<small class="help">${esc(a.evaluationExemptReason)}</small>`:''}</td></tr>`;}))}</section>`;}
function outputsView(p){if(!p.sessions.some(s=>s.id===printSession))printSession='';if(!p.panelists.some(x=>x.id===printPanel))printPanel='';return heading('인쇄할 대상에 맞게 준비하세요','A4 인쇄·PDF 저장을 지원합니다. 인쇄창을 열어도 실제 출력 완료로 처리하지 않습니다.')+`${Core.stalePrints(p).length?'<div class="notice">오래된 출력물이 있습니다. 최신 미리보기로 다시 인쇄하고 실물 버전을 확인해 주세요.</div>':''}<section class="card"><div class="filters"><label class="field">출력 묶음<select id="print-kind">${options(PRINT_KINDS,printKind)}</select></label><label class="field">회차<select id="print-session">${options([{value:'',label:'전체 회차'},...p.sessions.map(s=>({value:s.id,label:s.label}))],printSession)}</select></label>${['panel','evaluation'].includes(printKind)?`<label class="field">대상 위원<select id="print-panel">${options([{value:'',label:'전체 위원 공통'},...p.panelists.map(x=>({value:x.id,label:x.name}))],printPanel)}</select></label>`:''}<label class="field">용지 방향<select id="print-orientation">${options([{value:'portrait',label:'A4 세로'},{value:'landscape',label:'A4 가로'}],printOrientation)}</select></label></div><p class="notice info">${esc(PRINT_KINDS.find(x=>x.value===printKind)?.privacy||'출력물의 개인정보 범위를 확인하세요.')} · 문서 버전 v${p.revision}</p><div class="actions">${button('인쇄 / PDF 저장','print','','primary')}${button('출력 HTML 저장','print-download')}${button('실제 출력 확인','print-confirm')}</div><p class="help">평가표는 지원자마다 새 A4 페이지에서 시작합니다. 인쇄 배율 100%, 머리글·바닥글 끄기를 권장합니다. 긴 입력은 페이지가 추가될 수 있습니다.</p><iframe id="print-preview" class="print-preview" title="A4 인쇄 미리보기" sandbox="allow-same-origin allow-modals"></iframe></section><section class="card"><div class="card-header"><h2>MACH 제작기와 연결</h2><small>제작 완료 여부는 체크리스트에서 따로 확인합니다.</small></div><div class="grid-3"><div><h3>면접위원 명패</h3><p class="help">이름·소속·직위·역할만 명단 JSON으로 전달합니다.</p>${button('명패 만들기 ↗','nameplates')}</div><div><h3>현장 안내문</h3><p class="help">면접실·대기실·접수처·방향안내를 기존 제작기로 가져갑니다.</p>${button('안내문 만들기 ↗','notice-tool')}</div><div><h3>디지털 안내 화면</h3><p class="help">면접명·일시·장소를 기존 디지털 제작기의 작업 파일로 전달합니다.</p>${button('디지털 제작기 ↗','signage-tool')}</div></div></section>`;}
function updatePreview(){const el=$('#print-preview');if(!el)return;try{el.srcdoc=buildPrintDocument(project(),printKind,{sessionId:printSession||undefined,panelistId:['panel','evaluation'].includes(printKind)?printPanel||undefined:undefined,orientation:printOrientation,printedAt:new Date().toISOString()});}catch(e){toast('인쇄 미리보기: '+e.message);}}
function archiveView(p){return heading('저장하고, 변경사항을 확인하세요','이 브라우저의 내용은 다른 기기로 자동 동기화되지 않습니다. JSON 파일에는 개인정보가 포함됩니다.')+`<section class="card"><div class="grid-3"><div><h3>프로젝트 보관</h3><p class="help">지원자·평가·변경이력을 포함합니다. 승인된 위치에 보관하세요.</p>${button('이 프로젝트 JSON 저장','export-project','','primary')}</div><div><h3>전체 백업 / 복원</h3><p class="help">전체 면접 프로젝트를 파일로 보관하거나 검증 후 추가합니다.</p><div class="actions">${button('전체 백업','backup')}${button('JSON 복원','restore')}</div></div><div><h3>지난 설정 재사용</h3><p class="help">지원자·점수·결과·안내·출력 이력은 가져오지 않습니다.</p>${button('설정만 복제','clone',`data-id="${esc(p.id)}"`)}</div></div></section><section class="card"><h2>출력 버전</h2>${p.prints.length?table(['출력 대상','버전 / 시각','실물 확인'],p.prints.map(x=>`<tr><td>${esc(PRINT_KINDS.find(k=>k.value===x.kind)?.label||x.kind)}</td><td>v${x.revision} · ${esc(x.createdAt||x.printedAt||x.at||'')}<br>${badge(x.revision===p.revision?'최신':'재출력 필요',x.revision===p.revision?'good':'warn')}</td><td>${badge(x.confirmed?'출력 확인':'미확인',x.confirmed?'good':'')}</td></tr>`)):empty('출력 이력이 없습니다','출력 센터에서 인쇄를 실행하면 버전을 기록합니다.')}</section><section class="card"><h2>변경이력</h2>${p.history.length?table(['변경시각','내용','변경 전 → 후'],[...p.history].reverse().map(h=>`<tr><td>${esc(h.at||h.timestamp||h.createdAt)}</td><td>${esc(h.label||h.message||h.type||'변경')}<small class="help">${esc(h.number||h.applicantId||'')}</small></td><td>${esc(typeof h.before==='object'?JSON.stringify(h.before):h.before||'')} → ${esc(typeof h.after==='object'?JSON.stringify(h.after):h.after||'')}</td></tr>`)):empty('변경이력이 없습니다','확정 후 일정·장소·준비물이 바뀌면 변경 전후를 기록합니다.')}</section><section class="card"><h2>종료·보관 및 삭제</h2><p class="help">보관 검토일: ${esc(p.retentionDate||'미설정')} · 기관의 실제 개인정보 보관 기준에 따라 백업 위치와 삭제 시점을 정하세요. 외부 제작기로 내려받은 파일은 각 도구에서 별도로 관리해야 합니다.</p><div class="actions">${button(p.archived?'보관 해제':'종료 후 보관 표시','archive-toggle')}${button('지원자 개인정보 삭제','purge-applicants','','danger')}${button('프로젝트 삭제','delete-project','','danger')}</div></section>`;}
function editSession(id){const p=project(),s=copy(p.sessions.find(x=>x.id===id)||Core.newSession({label:`${p.sessions.length+1}회차`}));modal(id?'회차 설정 수정':'면접 회차 추가',`<div class="form-grid">${field('회차 이름','label',s.label,'text','예: 10/12 오전 A면접실','span-2')}${field('면접일','date',s.date,'date')}${field('시작시간','start',s.start,'time')}${field('종료시간','end',s.end,'time')}${select('면접 방식','mode',s.mode,[{value:'individual',label:'개인 면접'},{value:'group',label:'조별 면접'}])}${field('실제 면접시간 (분)','interviewMinutes',s.interviewMinutes,'number','질문과 답변에 사용하는 시간')}${field('평가·교체시간 (분)','turnoverMinutes',s.turnoverMinutes,'number','면접 후 점수 정리와 다음 입실')}${field('조별 인원','groupSize',s.groupSize,'number','조 전체가 한 슬롯을 함께 사용합니다.')}${field('도착권장 (분 전)','arrivalMinutes',s.arrivalMinutes,'number')}${field('모집분야 제한','field',s.field,'text','비우면 모든 분야. 입력 시 정확히 같은 분야만 배정.')}${textarea('휴식시간','breaks',s.breaks.map(b=>`${b.start}-${b.end}`).join('\n'),'한 줄에 한 구간. 예: 10:00-10:15')}${select('캠퍼스·지역','campus',s.venue.campus,['ERICA','서울','기타'])}${select('ERICA 건물','buildingId',s.venue.buildingId,[{value:'',label:'직접 입력 / 미정'},...Integrations.BUILDINGS.map(b=>({value:b.id,label:b.id+' '+b.nameKo}))])}${field('건물명 (직접 입력)','building',s.venue.building)}${field('면접실 / 호실','room',s.venue.room)}${field('대기실','waitingRoom',s.venue.waitingRoom)}${field('접수 위치','reception',s.venue.reception)}${field('장소 사용 시작','useStart',s.venue.useStart,'time','준비·정리 시간을 포함합니다.')}${field('장소 사용 종료','useEnd',s.venue.useEnd,'time')}${select('예약상태','reservation',s.venue.reservation,['미정','문의 중','예약 요청','예약 확정'])}${field('장소 연락메모','contact',s.venue.contact,'text','예약 연락처 등 담당자용 정보','full')}${textarea('장소 비고','memo',s.venue.memo)}<div class="field full"><p>이 회차 참여위원</p><div class="actions">${p.panelists.map(x=>checkbox(x.name,'panel-'+x.id,s.panelistIds.includes(x.id))).join('')||'<small>면접위원 화면에서 나중에 지정할 수 있습니다.</small>'}</div></div></div>`,(d,form)=>{let br=[];for(const line of d.breaks.split('\n').map(x=>x.trim()).filter(Boolean)){const m=line.match(/^(\d{2}:\d{2})\s*[-~]\s*(\d{2}:\d{2})$/);if(!m)throw Error('휴식은 10:00-10:15 형식으로 입력하세요.');br.push({start:m[1],end:m[2]});}const building=d.campus==='ERICA'?Integrations.BUILDINGS.find(b=>b.id===d.buildingId):null;Object.assign(s,{label:d.label.trim()||'면접 회차',date:d.date,start:d.start,end:d.end,mode:d.mode,interviewMinutes:+d.interviewMinutes,turnoverMinutes:+d.turnoverMinutes,groupSize:+d.groupSize,arrivalMinutes:+d.arrivalMinutes,field:d.field.trim(),breaks:br,panelistIds:p.panelists.filter(x=>form.elements['panel-'+x.id]?.checked).map(x=>x.id),venue:{campus:d.campus,buildingId:building?.id||'',building:building?.nameKo||d.building.trim(),room:d.room,waitingRoom:d.waitingRoom,reception:d.reception,useStart:d.useStart,useEnd:d.useEnd,reservation:d.reservation,contact:d.contact,memo:d.memo}});const errors=Core.sessionErrors(s);if(errors.length)throw Error(errors.join(' '));if(!Number.isInteger(s.arrivalMinutes)||s.arrivalMinutes<0||s.arrivalMinutes>180)throw Error('도착 권장은 0~180분으로 입력하세요.');if((d.useStart&&!d.useEnd)||(!d.useStart&&d.useEnd)||d.useStart&&(d.useStart>s.start||d.useEnd<s.end||d.useStart>=d.useEnd))throw Error('장소 사용시간은 면접 운영시간을 포함하도록 시작·종료를 모두 입력하세요.');return change(p=>{if(id)p.sessions[p.sessions.findIndex(x=>x.id===id)]=s;else p.sessions.push(s);},'회차 일정·장소 변경')!==false;});}
function editPanel(id){const x=project().panelists.find(x=>x.id===id)||{id:uid(),name:'',organization:'',position:'',role:'면접위원',contact:'',note:'',attendance:{}};modal(id?'면접위원 수정':'면접위원 등록',`<div class="form-grid">${field('이름','name',x.name)}${field('소속','organization',x.organization)}${field('직위','position',x.position)}${field('역할','role',x.role,'text','위원장 / 면접위원 / 진행자 / 기록자 또는 직접 입력')}${field('연락처 (선택)','contact',x.contact,'text','운영자용 출력에만 포함합니다.','span-2')}${textarea('비고','note',x.note)}</div>`,d=>{if(!d.name.trim())throw Error('이름을 입력하세요.');return change(p=>{const person={...copy(x),...d,name:d.name.trim()};if(id)p.panelists[p.panelists.findIndex(v=>v.id===id)]=person;else p.panelists.push(person);},'면접위원 변경')!==false;});}
function rangesText(ranges){return (ranges||[]).map(r=>r.date+(r.start?` ${r.start}-${r.end}`:'')).join(';');}
function editApplicant(id){const p=project(),a=p.applicants.find(x=>x.id===id)||Core.newApplicant(p);modal(id?'지원자 수정':'지원자 직접 입력',`<div class="form-grid">${field('이름','name',a.name)}${field('지원자번호','number',a.number,'text','기존 수험·접수번호 사용 가능. 비워 두면 자동생성.')}${field('연락처 (선택)','contact',a.contact)}${field('지원분야','field',a.field,'text','회차의 분야 제한과 같은 이름을 입력하세요.','full')}${textarea('가능시간','available',rangesText(a.available),'비우면 제한 없음. 예: 2026-10-12 09:00-12:00;2026-10-13')}${textarea('불가시간','unavailable',rangesText(a.unavailable),'예: 2026-10-12 10:00-11:00 (여러 구간은 ;로 구분)')}${textarea('일정변경 요청','changeRequest',a.changeRequest||'','요청을 기록해도 시간표는 자동으로 변경되지 않습니다.')}${textarea('운영 비고','note',a.note,'위원용·현장 게시용 출력에는 포함되지 않습니다.')}<div class="field full">${checkbox('특정 시간 고정','fixed',a.fixed)} ${checkbox('안내 후 잠금','locked',a.locked)}<span class="help">고정·잠금 지원자는 자동 재배정에서 제외됩니다. 배정 후 선택하세요.</span></div></div>`,(d,form)=>{if(!d.name.trim())throw Error('이름을 입력하세요.');const number=d.number.trim()||Core.nextApplicantNumber(p);if(p.applicants.some(x=>x.id!==a.id&&x.number===number))throw Error('같은 지원자번호가 있습니다. 다른 번호를 입력하세요.');if(!a.assignment&&(form.elements.fixed.checked||form.elements.locked.checked))throw Error('먼저 시간표에서 배정한 뒤 고정·잠금을 선택하세요.');const available=IO.parseTimeRanges(d.available),unavailable=IO.parseTimeRanges(d.unavailable);return change(p=>{const next={...copy(a),...d,number,name:d.name.trim(),available,unavailable,fixed:form.elements.fixed.checked,locked:form.elements.locked.checked};if(id)p.applicants[p.applicants.findIndex(x=>x.id===id)]=next;else p.applicants.push(next);},'지원자 정보 변경')!==false;});}
function moveDialog(id){const p=project(),a=p.applicants.find(x=>x.id===id);const opts=[{value:'',label:'미배정으로 두기'},...p.sessions.flatMap(s=>Core.generateSlots(s).map(slot=>({value:s.id+'|'+slot.start,label:`${s.date} ${s.label} ${slot.start} · ${p.applicants.filter(x=>x.assignment?.sessionId===s.id&&x.assignment?.start===slot.start&&x.status!=='참여취소').length}/${slot.capacity}명`})) )];modal(`${a.number} · ${a.name} 시간 배정`,`<div class="form-grid">${select('날짜·회차·시간','slot',a.assignment?a.assignment.sessionId+'|'+a.assignment.start:'',opts,'가능·불가시간과 정원을 확인한 뒤 이동합니다.','full')}<div class="field full">${checkbox('이 시간을 고정','fixed',a.fixed)} ${checkbox('안내 후 잠금','locked',a.locked)}</div><p class="help field full">이 창에서 이동을 저장하면 선택한 시간으로 명시적으로 변경합니다. 확정 안내 후 이동한 경우 재안내가 표시됩니다.</p></div>`,(d,form)=>{const [sessionId,start]=d.slot.split('|'),target=d.slot?{sessionId,start}:null;const v=Core.validateMove(p,id,target,{ignoreLock:true});if(!v.valid)throw Error(v.reasons.join(' '));if(!target&&(form.elements.fixed.checked||form.elements.locked.checked))throw Error('배정하지 않은 지원자는 고정·잠금할 수 없습니다.');return change(p=>{const next=p.applicants.find(x=>x.id===id);next.assignment=target;next.fixed=form.elements.fixed.checked;next.locked=form.elements.locked.checked;},'지원자 시간 이동')!==false;});}
function questionDialog(id){const p=project(),q=p.questions.find(x=>x.id===id)||{id:uid(),field:p.type,tag:'지원동기',text:'',minutes:2,criterionId:p.criteria[0]?.id||'',followUp:'',selected:true};modal(id?'질문 수정':'질문 작성',`<div class="form-grid">${select('질문 분야','field',q.field,QUESTION_FIELDS)}${select('질문 태그','tag',q.tag,QUESTION_TAGS)}${field('예상 소요시간 (분)','minutes',q.minutes,'number')}${textarea('질문','text',q.text)}${textarea('후속질문','followUp',q.followUp)}${select('연결 평가항목','criterionId',q.criterionId,[{value:'',label:'미연결'},...p.criteria.map(c=>({value:c.id,label:c.label}))],'질문이 어떤 평가항목을 확인하는지 연결하세요.','full')}</div>`,d=>{if(!d.text.trim())throw Error('질문을 입력하세요.');if(+d.minutes<1||+d.minutes>60)throw Error('질문 예상시간은 1~60분으로 입력하세요.');return change(p=>{const next={...copy(q),...d,minutes:+d.minutes};if(id)p.questions[p.questions.findIndex(x=>x.id===id)]=next;else p.questions.push(next);},'면접 질문 변경')!==false;});}
function criterionDialog(id){const p=project();if(!id&&p.criteria.length>=10)return toast('A4 평가표를 위해 평가항목은 10개까지 등록할 수 있습니다.');const c=p.criteria.find(x=>x.id===id)||{id:uid(),label:'',max:20,description:'',rubric:''};modal(id?'평가항목 수정':'평가항목 추가',`<div class="form-grid">${field('항목명','label',c.label,'text','80자 이내','span-2')}${field('배점','max',c.max,'number')}${textarea('평가내용 설명','description',c.description)}${textarea('평가기준 (rubric)','rubric',c.rubric,'예: 충분한 근거와 구체적 사례가 있으면 16~20점')}</div>`,d=>{if(!d.label.trim()||d.label.length>80)throw Error('평가항목명은 1~80자로 입력하세요.');if(!Number.isFinite(+d.max)||+d.max<=0||+d.max>1000)throw Error('배점은 1~1000점으로 입력하세요.');return change(p=>{const next={...copy(c),...d,max:+d.max};if(id)p.criteria[p.criteria.findIndex(x=>x.id===id)]=next;else p.criteria.push(next);p.applicants.forEach(a=>a.resultConfirmed=false);},'평가 기준 변경')!==false;});}
function previewImport(raw,notes=[]){const preview=IO.importRows(project(),raw);preview.warnings.push(...notes);importPreview=preview;modal('지원자 가져오기 미리보기',`<p>${preview.rows.length}개 행 · 기존 지원자는 유지하고 새로 추가합니다.</p>${preview.errors.map(e=>`<div class="notice error">${esc(e)}</div>`).join('')}${preview.warnings.map(e=>`<div class="notice">${esc(e)}</div>`).join('')}<div class="review-lines">${table(['번호','이름','연락처','분야'],preview.applicants.slice(0,100).map(a=>`<tr><td>${esc(a.number)}</td><td>${esc(a.name)}</td><td>${esc(a.contact)}</td><td>${esc(a.field)}</td></tr>`))}</div>${preview.applicants.length>100?'<p class="help">앞 100명만 미리보기에 표시합니다. 전체 인원이 등록됩니다.</p>':''}`,()=>{if(preview.errors.length)throw Error('오류를 수정한 파일로 다시 가져오세요.');const result=change(p=>p.applicants.push(...preview.applicants),'지원자 명단 가져오기');if(result!==false)toast(`${preview.applicants.length}명을 등록했습니다.`);return result!==false;},preview.errors.length?null:`${preview.applicants.length}명 등록`);}
function cloneDialog(id){const p=projects.find(x=>x.id===id);modal('지난 면접 설정 가져오기',`<p>‘${esc(p.name)}’의 질문·평가항목·운영조건·체크리스트·안내문을 복제합니다. 지난 지원자, 연락처, 점수, 의견, 결과, 발송·출력 이력은 복제하지 않습니다.</p><div class="form-grid">${field('새 프로젝트명','name',p.name+' (복제)','text','','full')}<div class="field full">${checkbox('장소 설정 가져오기','venue')} ${checkbox('위원 Pool 가져오기 (연락처 제외)','panelists')}</div></div>`,(d,form)=>{const next=Core.cloneProject(p,{venue:form.elements.venue.checked,panelists:form.elements.panelists.checked});next.name=d.name.trim()||p.name+' (복제)';projects.push(next);activeId=next.id;persist();view='settings';render();toast('설정만 복제했습니다. 날짜와 참석확인을 새로 입력하세요.');});}
function toolDialog(kind){const p=project();if(kind==='nameplate'){if(!p.panelists.length)return toast('면접위원을 먼저 등록하세요.');modal('면접위원 명패 만들기',`<p>처음 만들거나 다른 행사를 작업 중이면 제작기의 기존 작업을 먼저 저장한 뒤, <strong>작업 불러오기</strong>에서 새 작업 JSON을 여세요.</p>${select('전달 방식','handoff','project',[{value:'project',label:'새 면접 명패 작업 (작업 불러오기)'},{value:'roster',label:'같은 면접 명단 갱신 (변경분 JSON 가져오기)'}],'같은 면접의 기존 디자인을 유지하며 명단을 갱신할 때는 변경분을 선택하세요.','full')}<p class="help">이름·소속·직위·역할을 전달합니다. 연락처·지원자 정보는 포함하지 않습니다. 다른 행사의 명단과 자동으로 합치지 않습니다.</p><div class="actions"><a class="button" href="${Integrations.TOOL_URLS.nameplate}" target="_blank" rel="noopener noreferrer">기존 명패 제작기 열기 ↗</a></div>`,d=>{const fresh=d.handoff==='project';download(JSON.stringify(fresh?Integrations.nameplateProjectPayload(p):Integrations.nameplatePayload(p),null,2),fresh?'면접위원-명패-작업.json':'면접위원-명패-MACH.json');toast(fresh?'명패 작업 JSON을 저장했습니다. 제작기의 작업 불러오기에서 여세요.':'변경분 JSON을 저장했습니다. 제작기의 변경분 JSON 가져오기에서 여세요.');},'명패 JSON 저장');return;}
 if(!p.sessions.length)return toast('일정·장소에서 회차를 먼저 등록하세요.');modal(kind==='notice'?'안내문 만들기':'디지털 안내 화면 만들기',`<p>기존 제작기의 <strong>작업 불러오기</strong>에서 JSON 파일을 선택하면 면접명·일시·장소가 채워집니다.</p><div class="form-grid">${select('대상 회차','session',p.sessions[0].id,p.sessions.map(s=>({value:s.id,label:s.label})),'','full')}${select('안내유형','type','면접실',Integrations.NOTICE_TYPES||['면접실','대기실','접수처'])}${field('방향','direction','→','text','예: 왼쪽 / 2층 / →')}</div><div class="actions" style="margin-top:18px"><a class="button" href="${Integrations.TOOL_URLS[kind==='notice'?'notice':'signage']}" target="_blank" rel="noopener noreferrer">기존 제작기 열기 ↗</a></div>`,d=>{const s=p.sessions.find(x=>x.id===d.session),payload=kind==='notice'?Integrations.noticePayload(p,s,d.type,d.direction):Integrations.signagePayload(p,s);download(JSON.stringify(payload,null,2),`면접-${kind==='notice'?'안내문':'디지털'}-작업.json`);},'제작기용 작업 JSON 저장');}
function openWaiting(){const p=project(),selected=sessionFilter?p.sessions.filter(s=>s.id===sessionFilter):p.sessions,people=p.applicants.filter(a=>selected.some(s=>s.id===a.assignment?.sessionId));const current=people.filter(a=>a.status==='면접 중'),wait=people.filter(a=>['도착·대기','예정','지각'].includes(a.status)).sort((a,b)=>`${sessionFor(a)?.date} ${a.assignment.start}`.localeCompare(`${sessionFor(b)?.date} ${b.assignment.start}`));$('#app').innerHTML=`<div class="wait-screen"><div class="row-between"><div><div class="eyebrow" style="color:#a6c5f2">INTERVIEW CALL BOARD</div><h1>면접 순서 안내</h1></div>${button('운영 화면으로','waiting-close')}</div><p>지원자번호로 확인해 주세요. 진행 상황에 따라 담당자가 안내합니다.</p><div class="wait-grid"><section class="wait-card"><div class="wait-label">현재 면접 중</div><div class="wait-number">${current.map(a=>esc(a.number)).join('<br>')||'대기 중'}</div></section><section class="wait-card"><div class="wait-label">다음 예정</div><div class="wait-number">${wait.slice(0,3).map(a=>esc(a.number)).join('<br>')||'—'}</div></section></div><p class="footer-note" style="color:#a6c5f2">번호·호출상태만 표시하는 화면입니다. ${button('호출 현황 새로 표시','waiting-display','','small-btn')}</p></div>`;}
$('#app').addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;e.preventDefault();const action=target.dataset.action,id=target.dataset.id,p=project();try{switch(action){
case 'home':activeId=null;persist();render();break;
case 'nav':nav(target.dataset.view);break;
case 'open-project':activeId=id;view='overview';sessionFilter='';persist();render();break;
case 'new':modal('새 면접 만들기',`<div class="form-grid">${field('프로젝트명','name','','text','예: 2026 가을 홍보 서포터즈 면접','full')}${select('면접유형','type','학생단체',INTERVIEW_TYPES,'유형에 맞는 예시 질문·평가표가 준비됩니다.','full')}</div>`,d=>{if(!d.name.trim())throw Error('프로젝트명을 입력하세요.');const next=Core.createProject(d.type);next.name=d.name.trim();projects.push(next);activeId=next.id;persist();view='overview';render();});break;
case 'demo':{const next=Core.createDemo();projects.push(next);activeId=next.id;persist();view='overview';render();toast('가상 지원자로 만든 예시입니다. 자유롭게 수정해 보세요.');break;}
case 'clone-select':if(!projects.length){toast('지난 프로젝트가 없습니다. JSON 복원으로 가져온 뒤 설정을 복제할 수 있습니다.');break;}modal('지난 면접 선택',select('복제할 프로젝트','source',projects[0].id,projects.map(x=>({value:x.id,label:x.name}))),d=>{setTimeout(()=>cloneDialog(d.source),0);},'설정 선택');break;
case 'clone':cloneDialog(id);break;
case 'session-add':editSession();break;case 'session-edit':editSession(id);break;
case 'session-delete':if(p.applicants.some(a=>a.assignment?.sessionId===id)){toast('배정된 지원자가 있는 회차입니다. 먼저 지원자를 다른 회차로 이동하거나 미배정으로 바꾸세요.');break;}confirmAction('회차 삭제','회차와 장소 설정을 삭제합니다. 계속하시겠습니까?',()=>change(p=>{p.sessions=p.sessions.filter(s=>s.id!==id);},'회차 삭제'));break;
case 'panel-add':editPanel();break;case 'panel-edit':editPanel(id);break;
case 'panel-delete':confirmAction('면접위원 삭제','회차 참여목록에서도 제외됩니다. 해당 위원의 평가가 있다면 먼저 JSON으로 보관하세요.',()=>change(p=>{p.panelists=p.panelists.filter(x=>x.id!==id);p.sessions.forEach(s=>s.panelistIds=s.panelistIds.filter(x=>x!==id));p.applicants.forEach(a=>{delete a.evaluations[id];a.resultConfirmed=false;});},'면접위원 삭제'));break;
case 'applicant-add':editApplicant();break;case 'applicant-edit':editApplicant(id);break;
case 'applicant-delete':confirmAction('지원자 삭제','이 지원자의 배정·평가·결과를 삭제합니다. 되돌리려면 기존 JSON 백업이 필요합니다.',()=>change(p=>{p.applicants=p.applicants.filter(a=>a.id!==id);p.history=p.history.filter(h=>h.applicantId!==id);},'지원자 삭제'));break;
case 'move':moveDialog(id);break;
case 'paste':modal('여러 행 붙여넣기',textarea('Excel에서 복사한 행 또는 CSV','rows','','머리글 권장: 지원자번호, 이름, 연락처, 지원분야, 비고, 가능시간, 불가시간. 머리글 없이 이름·연락처·분야·비고 순서도 가능합니다.'),d=>{const rows=IO.parseDelimited(d.rows);setTimeout(()=>previewImport(rows),0);},'미리보기');break;
case 'import-applicants':chooseFile('applicants','.csv,.tsv,.xlsx,.xls');break;
case 'import-template':download('\uFEFF'+IO.IMPORT_SAMPLE,'면접-지원자-가져오기-양식.csv','text/csv;charset=utf-8');break;
case 'auto-assign':confirmAction('자동배정 실행',`${p.confirmed?'확정된 시간표입니다. 변경된 지원자는 재안내 대상이 됩니다. ':''}고정·잠금 지원자는 유지하고 나머지를 날짜·가능시간·모집분야에 맞춰 다시 배정합니다.`,()=>{let result;const saved=change(p=>{result=Core.autoAssign(p);if(result.aborted)throw Error(result.issues.map(x=>x.message).join(' '));},'시간표 자동배정');if(saved!==false)toast(`${result.assigned}명 배정 · ${result.unassigned}명 미배정 · 고정/잠금 ${result.preserved}명 유지`);return saved!==false;},'배정하기');break;
case 'confirm-schedule':{const trial=copy(p),r=Core.confirmSchedule(trial);if(!r.valid){modal('시간표 확정 전 확인',`<div class="notice">${r.issues.map(x=>esc(typeof x==='string'?x:x.message)).join('<br>')}</div>`,()=>{},'닫기');break;}confirmAction('시간표 확정','지원자별 날짜·시간·장소를 검토했습니다. 확정 후 안내를 발송하고 발송확인을 기록할 수 있습니다.',()=>change(p=>{const r=Core.confirmSchedule(p);if(!r.valid)throw Error(r.issues.map(x=>typeof x==='string'?x:x.message).join(' '));},'시간표 확정'),'검토 완료 · 확정');break;}
case 'unconfirm-schedule':confirmAction('시간표 확정 해제','초안 상태로 바꿉니다. 기존 발송·잠금 기록은 유지되며 이후 변경 시 재안내가 필요합니다.',()=>change(p=>{p.confirmed=false;},'시간표 확정 해제'));break;
case 'simulate':{const n=+document.querySelector('[name="plannedCount"]').value;if(!Number.isInteger(n)||n<0||n>5000)throw Error('계획 인원은 0~5,000명으로 입력하세요.');change(p=>p.plannedCount=n,'계획 인원 변경');break;}
case 'question-add':questionDialog();break;case 'question-edit':questionDialog(id);break;
case 'question-delete':change(p=>p.questions=p.questions.filter(q=>q.id!==id),'질문 삭제');break;
case 'question-up':change(p=>{const i=p.questions.findIndex(q=>q.id===id);if(i>0)[p.questions[i-1],p.questions[i]]=[p.questions[i],p.questions[i-1]];},'질문 순서 변경');break;
case 'bank-add':change(p=>p.questions.push({...copy(QUESTION_BANK.find(q=>q.id===id)),id:uid(),selected:true}),'질문은행에서 추가');toast('질문을 담았습니다. 면접 질문 목록에서 수정할 수 있습니다.');break;
case 'criterion-add':criterionDialog();break;case 'criterion-edit':criterionDialog(id);break;
case 'criterion-up':change(p=>{const i=p.criteria.findIndex(q=>q.id===id);if(i>0)[p.criteria[i-1],p.criteria[i]]=[p.criteria[i],p.criteria[i-1]];},'평가항목 순서 변경');break;
case 'criterion-delete':confirmAction('평가항목 삭제','평가표 구성에서 제외합니다. 기존 점수는 백업에 남지만 새 총점에는 포함되지 않습니다.',()=>change(p=>{const removed=p.criteria.find(q=>q.id===id);p.criteria=p.criteria.filter(q=>q.id!==id);p.applicants.forEach(a=>{for(const ev of Object.values(a.evaluations)){if(Object.hasOwn(ev.scores,id)){ev.archivedScores||=[];ev.archivedScores.push({criterion:removed,score:ev.scores[id],archivedAt:new Date().toISOString()});delete ev.scores[id];}}a.resultConfirmed=false;});},'평가항목 삭제'));break;
case 'target-score':{const n=+document.querySelector('[name="targetScore"]').value;if(!Number.isFinite(n)||n<1||n>10000)throw Error('목표 총점은 1~10,000점으로 입력하세요.');change(p=>p.targetScore=n,'목표 총점 변경');break;}
case 'print-evaluation':printKind='evaluation';nav('outputs');break;
case 'template-edit':modal('안내문 템플릿 수정',textarea(p.templates[templateKey].label,'text',p.templates[templateKey].text,'{이름}, {번호}, {면접명} 등의 변수를 그대로 사용하세요.'),d=>change(p=>p.templates[templateKey].text=d.text,'안내 템플릿 변경'));break;
case 'message-copy':{const a=p.applicants.find(x=>x.id===id);const text=messageText(p,a,templateKey);await clipboard(text);change(p=>{const a=p.applicants.find(x=>x.id===id),key=isResultTemplate(templateKey)?'resultMessage':'message';a[key]||={};a[key].generated=true;a[key].generatedAt=new Date().toISOString();},'안내문 생성');break;}
case 'messages-copy':{const list=p.applicants.filter(a=>messageAllowed(p,a,templateKey)&&(messageFilter!=='changed'||a.message.needsUpdate)&&(messageFilter!=='unsent'||!(isResultTemplate(templateKey)?a.resultMessage:a.message)?.sent));if(!list.length)throw Error('복사할 대상이 없습니다.');await clipboard(list.map(a=>messageText(p,a,templateKey)).join('\n\n──────────\n\n'));change(p=>list.forEach(a=>{const key=isResultTemplate(templateKey)?'resultMessage':'message';a[key]||={};a[key].generated=true;}),'안내문 전체 생성');break;}
case 'message-sent':{if(!isResultTemplate(templateKey)&&!p.confirmed)throw Error('시간표를 먼저 확정하세요.');confirmAction('실제 발송 확인','해당 지원자에게 내용을 직접 발송한 경우에만 확인하세요. 일정 안내 발송확인은 시간배정을 잠급니다.',()=>change(p=>{const a=p.applicants.find(x=>x.id===id),key=isResultTemplate(templateKey)?'resultMessage':'message';a[key]||={};Object.assign(a[key],{generated:true,sent:true,sentAt:new Date().toISOString(),needsUpdate:false,replied:false});if(!isResultTemplate(templateKey))a.locked=true;},'발송 확인'),'발송했음');break;}
case 'message-replied':change(p=>{const a=p.applicants.find(x=>x.id===id),key=isResultTemplate(templateKey)?'resultMessage':'message';a[key]||={};if(!a[key].sent)throw Error('발송확인 후 회신확인을 기록하세요.');a[key].replied=!a[key].replied;},'회신 확인');break;
case 'map-copy':{const s=p.sessions.find(x=>x.id===id);await clipboard(`${s.venue.building} ${s.venue.room}\n${Integrations.mapLink(s)}\n${Integrations.locationInfo(s).guidance}`);break;}
case 'nameplates':toolDialog('nameplate');break;case 'notice-tool':toolDialog('notice');break;case 'signage-tool':toolDialog('signage');break;
case 'waiting-display':openWaiting();break;case 'waiting-close':view='operations';render();break;
case 'timer-toggle':if(timerRunning){timerElapsed+=Date.now()-timerStart;timerRunning=false;}else{timerRunning=true;timerStart=Date.now();}render();break;
case 'timer-reset':timerRunning=false;timerElapsed=0;render();break;
case 'evaluation-save':{const inputs=[...document.querySelectorAll('[data-score-applicant]')].filter(el=>el.dataset.scoreApplicant===id);const scores={};for(const input of inputs){const c=p.criteria.find(c=>c.id===input.dataset.criterion),value=input.value===''?'':Number(input.value);if(value!==''&&(!Number.isFinite(value)||value<0||value>c.max))throw Error(`${c.label} 점수는 0~${c.max}점 또는 빈칸으로 입력하세요.`);scores[c.id]=value;}if(change(p=>{const a=p.applicants.find(a=>a.id===id);a.evaluations[evaluationPanel]||={scores:{},comment:''};a.evaluations[evaluationPanel].scores=scores;a.resultConfirmed=false;},'위원 평가 입력')!==false)toast('위원 점수를 저장했습니다.');break;}
case 'evaluation-comment':{const a=p.applicants.find(x=>x.id===id);modal('위원 종합의견',textarea('종합의견','comment',a.evaluations?.[evaluationPanel]?.comment||''),d=>change(p=>{const a=p.applicants.find(x=>x.id===id);a.evaluations[evaluationPanel]||={scores:{}};a.evaluations[evaluationPanel].comment=d.comment;a.resultConfirmed=false;},'평가 의견 변경'));break;}
case 'evaluation-details':{const a=p.applicants.find(x=>x.id===id),s=Core.evaluationSummary(p,a);modal(`${a.number} 평가 상태`,s.expected?`<p>${s.countComplete} / ${s.expected}명 위원 평가 완료</p>${s.evaluations.map(ev=>`<div class="review-line"><strong>${esc(p.panelists.find(x=>x.id===ev.panelistId)?.name)}</strong><br>${ev.complete?'합계 '+ev.total+'점':'미입력: '+ev.missing.map(id=>esc(p.criteria.find(c=>c.id===id)?.label||id)).join(', ') + (ev.invalid.length?' / 범위 오류: '+ev.invalid.map(id=>esc(p.criteria.find(c=>c.id===id)?.label||id)).join(', '):'')}</div>`).join('')}`:'<p>배정된 회차의 참여위원을 먼저 지정하세요.</p>',()=>{},'닫기');break;}
case 'evaluation-exempt':{const a=p.applicants.find(x=>x.id===id);modal('평가 제외 사유 기록',textarea('담당자가 확인한 사유','reason',a.evaluationExemptReason||'','예: 지원자가 참여를 취소해 평가하지 않음. 사유만 기록해도 결과는 자동 확정되지 않습니다.'),d=>change(p=>{const a=p.applicants.find(x=>x.id===id);a.evaluationExemptReason=d.reason.trim();a.resultConfirmed=false;},'평가 제외 사유 변경'));break;}
case 'finalize-results':finalizeDialog();break;
case 'print':{const record=Core.recordPrint(p,printKind,{sessionId:printSession,panelistId:['panel','evaluation'].includes(printKind)?printPanel:'',orientation:printOrientation});persist();const frame=$('#print-preview');frame.contentWindow.focus();frame.contentWindow.print();toast('인쇄창을 열었습니다. 실물 출력은 별도로 확인해 주세요.');break;}
case 'print-download':{const cssText=await (await fetch(new URL('./print.css',import.meta.url))).text();download(buildPrintDocument(p,printKind,{sessionId:printSession||undefined,panelistId:['panel','evaluation'].includes(printKind)?printPanel||undefined:undefined,orientation:printOrientation,printedAt:new Date().toISOString(),cssText}),'면접-'+printKind+'-v'+p.revision+'.html','text/html');break;}
case 'print-confirm':confirmAction('실제 출력 확인','현재 미리보기와 같은 v'+p.revision+' 자료의 실제 출력 또는 PDF 저장을 확인했습니까?',()=>{let record=[...p.prints].reverse().find(x=>x.kind===printKind&&x.revision===p.revision&&(x.sessionId||'')===printSession&&(x.panelistId||'')===(['panel','evaluation'].includes(printKind)?printPanel:''));if(!record)record=Core.recordPrint(p,printKind,{sessionId:printSession,panelistId:['panel','evaluation'].includes(printKind)?printPanel:'',orientation:printOrientation});record.confirmed=true;record.confirmedAt=new Date().toISOString();persist();render();},'출력 확인');break;
case 'export-project':download(Core.exportBackup([p]),'면접-'+safeFilename(p.name)+'.json');break;
case 'backup':download(Core.exportBackup(projects),'면접-전체백업-'+new Date().toISOString().slice(0,10)+'.json');break;
case 'restore':chooseFile('restore','.json');break;
case 'archive-toggle':change(p=>p.archived=!p.archived,'보관 상태 변경');break;
case 'delete-project':confirmAction('프로젝트 삭제','지원자·평가·결과·변경이력을 포함한 프로젝트 전체를 이 브라우저에서 삭제합니다. 먼저 JSON 백업이 있는지 확인하세요.',()=>{projects=projects.filter(x=>x.id!==p.id);activeId=null;persist();render();},'프로젝트 삭제');break;
case 'purge-applicants':confirmAction('지원자 개인정보 삭제','지원자 명단·평가·결과·변경이력·출력기록을 삭제합니다. 질문과 평가항목·장소·위원 설정은 유지됩니다. 외부에 저장한 파일은 별도로 삭제해야 합니다.',()=>{const saved=copy(p);try{Core.purgeApplicantData(p);persist();render();}catch(e){projects[projects.findIndex(x=>x.id===p.id)]=saved;throw e;}},'개인정보 삭제');break;
case 'checklist-edit':{const c=p.checklist.find(c=>c.id===id);modal('체크리스트 항목 수정',field('항목명','label',c.label),d=>{if(!d.label.trim())throw Error('항목명을 입력하세요.');return change(p=>p.checklist.find(c=>c.id===id).label=d.label.trim(),'체크리스트 수정');});break;}
case 'checklist-add':modal('체크리스트 항목 추가',field('항목명','label','','text'),d=>{if(!d.label.trim())throw Error('항목명을 입력하세요.');return change(p=>p.checklist.push({id:uid(),label:d.label.trim(),done:false,due:''}),'체크리스트 추가');});break;
}}catch(err){toast(err.message);}});
function safeFilename(s){return String(s).replace(/[\\/:*?"<>|]/g,'-').slice(0,60);}
function finalizeDialog(){const p=project();const problems=[];if(!p.applicants.length)problems.push('지원자가 없습니다.');if(Core.scoreWarnings(p).length)problems.push('평가표 배점 합계를 확인하세요.');for(const a of p.applicants){if(a.result==='미정')problems.push(`${a.number}: 결과 미정`);if(!Core.evaluationSummary(p,a).complete&&!a.evaluationExemptReason)problems.push(`${a.number}: 평가 미완료 (제외 대상은 사유를 기록하세요)`);if(a.result==='예비합격'&&(!Number.isInteger(a.reserveRank)||a.reserveRank<1))problems.push(`${a.number}: 예비순번 필요`);}const ranks=p.applicants.filter(a=>a.result==='예비합격');if(ranks.some((a,i)=>ranks.slice(0,i).some(b=>b.field===a.field&&b.reserveRank===a.reserveRank)))problems.push('같은 모집분야의 예비순번이 중복되었습니다.');if(problems.length){modal('결과 확정 전 확인',`<div class="notice">${problems.map(esc).join('<br>')}</div>`,()=>{},'닫기');return;}modal('담당자 최종 결과 확정',`${table(['결과','인원'],RESULTS.filter(r=>r!=='미정').map(r=>`<tr><td>${r}</td><td>${p.applicants.filter(a=>a.result===r).length}명</td></tr>`))}<div class="list-stack" style="margin-top:20px">${checkbox('지원자별 결과와 예비순번을 검토했습니다.','review1')}${checkbox('평가 누락·제외사유를 확인했고 담당자로서 확정합니다.','review2')}</div><p class="help">자동 합격 추천은 하지 않습니다. 이 확인은 담당자의 명시적 확정 기록입니다.</p>`,(d,f)=>{if(!f.elements.review1.checked||!f.elements.review2.checked)throw Error('두 가지 검토를 모두 확인하세요.');const saved=change(p=>{p.applicants.forEach(a=>{a.resultConfirmed=true;a.resultConfirmedAt=new Date().toISOString();});p.resultsConfirmedAt=new Date().toISOString();},'담당자 최종 결과 확정');if(saved===false)return false;toast('담당자 최종 결과로 확정했습니다.');},'최종 확정');}
$('#dialog').addEventListener('click',e=>{if(e.target.closest('[data-action="close-dialog"]')){e.preventDefault();$('#dialog').close();}});
$('#app').addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.name.trim())return toast('프로젝트명을 입력하세요.');if(d.endDate&&d.startDate&&d.endDate<d.startDate)return toast('운영기간 종료일을 확인하세요.');if(change(p=>Object.assign(p,d),'면접 기본정보 변경')!==false)toast('기본정보를 저장했습니다.');}});
$('#app').addEventListener('keydown',e=>{if(e.target.id==='applicant-search'&&e.key==='Enter'){applicantSearch=e.target.value;render();}});
$('#app').addEventListener('change',e=>{const el=e.target,d=el.dataset;try{
if(el.id==='applicant-filter'){filter=el.value;render();}if(el.id==='applicant-search'){applicantSearch=el.value;render();}if(el.id==='bank-field'){bankField=el.value;render();}if(el.id==='message-template'){templateKey=el.value;render();}if(el.id==='message-filter'){messageFilter=el.value;render();}if(el.id==='session-filter'){sessionFilter=el.value;render();}if(el.id==='evaluation-panel'){evaluationPanel=el.value;render();}if(el.id==='print-kind'){printKind=el.value;render();}if(el.id==='print-session'){printSession=el.value;render();}if(el.id==='print-panel'){printPanel=el.value;render();}if(el.id==='print-orientation'){printOrientation=el.value;render();}
if(d.check)change(p=>p.checklist.find(c=>c.id===d.check).done=el.checked,'준비상태 확인');
if(d.deadline)change(p=>p.checklist.find(c=>c.id===d.deadline).due=el.value,'준비기한 변경');
if(d.questionSelected)change(p=>p.questions.find(q=>q.id===d.questionSelected).selected=el.checked,'사용 질문 변경');
if(d.panelSession)change(p=>{const s=p.sessions.find(s=>s.id===d.panelSession);s.panelistIds=el.checked?[...new Set([...s.panelistIds,d.id])]:s.panelistIds.filter(id=>id!==d.id);},'회차 참여위원 변경');
if(d.attendance)change(p=>{const x=p.panelists.find(x=>x.id===d.id);x.attendance||={};x.attendance[d.attendance]=el.value;},'위원 참석확인');
if(d.status)change(p=>p.applicants.find(a=>a.id===d.status).status=el.value,'현장 상태 변경');

if(d.result)change(p=>{const a=p.applicants.find(a=>a.id===d.result);a.result=el.value;a.resultConfirmed=false;a.resultMessage={generated:false,sent:false,replied:false};},'담당자 결과 입력');
if(d.rank)change(p=>{const a=p.applicants.find(a=>a.id===d.rank);if(el.value&&(!Number.isInteger(+el.value)||+el.value<1))throw Error('예비순번은 1 이상의 정수로 입력하세요.');a.reserveRank=el.value?+el.value:null;a.resultConfirmed=false;a.resultMessage={generated:false,sent:false,replied:false};},'예비순번 변경');
}catch(err){toast(err.message);render();}});
let dragging=null;$('#app').addEventListener('dragstart',e=>{const item=e.target.closest('[data-person]');if(item){dragging=item.dataset.person;e.dataTransfer.setData('text/plain',dragging);}});$('#app').addEventListener('dragover',e=>{const slot=e.target.closest('[data-slot-session]');if(slot){e.preventDefault();slot.classList.add('dragover');}});$('#app').addEventListener('dragleave',e=>e.target.closest('[data-slot-session]')?.classList.remove('dragover'));$('#app').addEventListener('drop',e=>{const slot=e.target.closest('[data-slot-session]');if(!slot)return;e.preventDefault();slot.classList.remove('dragover');if(!dragging)return;change(p=>{const result=Core.moveApplicant(p,dragging,{sessionId:slot.dataset.slotSession,start:slot.dataset.start});if(!result.valid)throw Error(result.reasons.join(' '));},'지원자 끌어서 시간 이동');dragging=null;});
function chooseFile(mode,accept){const input=$('#file-input');input.dataset.mode=mode;input.accept=accept;input.value='';input.click();}
$('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(e.target.dataset.mode==='applicants'){const result=await IO.importFile(file);previewImport(result.rows,[...result.warnings,`${result.sheetName?'첫 번째 시트: '+result.sheetName+' · ':''}${result.encoding} 형식으로 읽었습니다.`]);}else{if(file.size>10*1024*1024)throw Error('백업은 10MB 이내로 가져오세요.');const data=Core.validateBackup(await file.text());if(!data.valid)throw Error(data.errors.join(' '));const duplicate=data.projects.filter(p=>projects.some(x=>x.id===p.id));modal('JSON 복원 확인',`<p>${data.projects.length}개 프로젝트의 형식 검증이 끝났습니다.</p><p>${duplicate.length?`동일 ID ${duplicate.length}개는 현재 버전을 교체하고, 나머지는 추가합니다. 교체 전 현재 전체 백업 파일을 자동 저장합니다.`:'기존 프로젝트를 유지하고 가져온 프로젝트를 추가합니다.'}</p>${data.projects.map(p=>`<div class="review-line">${esc(p.name)} · ${p.applicants.length}명</div>`).join('')}`,()=>{if(duplicate.length)download(Core.exportBackup(projects),'복원전-전체백업.json');if(blocked){const stored=localStorage.getItem(STORAGE_KEY);if(stored)download(stored,'복원전-브라우저원본.json');let current=null;try{current=stored?JSON.parse(stored):null;}catch{localStorage.removeItem(STORAGE_KEY);}stamp=current?.stamp??null;blocked=false;$('#storage-alert').hidden=true;}const ids=new Set(data.projects.map(p=>p.id));projects=[...projects.filter(p=>!ids.has(p.id)),...data.projects];activeId=data.projects[0]?.id||null;persist();view='overview';render();toast('검증한 프로젝트를 복원했습니다.');},'복원하기');}}catch(err){toast(err.message);}});
render();
